Im in a situation when im required to save the name of the function from a decorator:

```
# ugly
def _hack_generator_name(fn):
    if not inspect.isgeneratorfunction(fn):
        return fn.__name__
    try:
        fn()
    except Exception as e:
        name = str(e)
        return name[:name.index("(")]


def optional_arg_decorator(fn):
    def wrapped_decorator(*args):
        if len(args) == 1 and callable(args[0]):
            return fn(args[0])
        else:
            def real_decorator(decoratee):
                return fn(decoratee, *args)
            return real_decorator

    return wrapped_decorator


@optional_arg_decorator
def httppost(fn, path=None, name=None):
    _decorator_list.append((_hack_generator_name(fn), path, Request.POST))
    return fn


@optional_arg_decorator
def httpget(fn, path=None, name=None):
    _decorator_list.append((_hack_generator_name(fn), path, Request.GET))
    return fn
```

But `fn.__name__ ` is missing from generator functions.

I solve this issue temporary by using an ugly hack (by calling the method and finding the name from the exception...)
